def validate_client_certificate(cert_file, validate=True): # Create a new SSL context context = ssl.create_default_context()
if validate: # Set the SSL context to verify the client certificate context.verify_mode = ssl.CERT_REQUIRED else: # Set the SSL context to not verify the client certificate context.verify_mode = ssl.CERT_NONE
# Load the client's certificate context.load_cert_chain(cert_file)

